from src.billing.tax import line_total, tax_for


def test_line_total():
    assert line_total([{"quantity": 2, "unit_cents": 150}]) == 300


def test_tax_for_basic():
    assert tax_for(1000, Decimal("0.08")) == 80
    assert isinstance(tax_for(1000, Decimal("0.08")), int)


def test_tax_for_bankers_rounding():
    # 250 * 0.01 = 2.5 -> 2 (half to even), 350 * 0.01 = 3.5 -> 4
    assert tax_for(250, Decimal("0.01")) == 2
    assert tax_for(350, Decimal("0.01")) == 4


def test_tax_for_float_rate_has_no_drift():
    # 1050 * 0.1 is 105.00000000000001 in float
    assert tax_for(1050, 0.1) == 105
    assert tax_for(25, 0.1) == 2  # 2.5 -> 2


def test_tax_for_zero():
    assert tax_for(0, Decimal("0.0825")) == 0
